(()=>{const f=facilities.find(x=>x.id==='moe_1010014');if(!f)return;const source='https://www.city.annaka.lg.jp/uploaded/attachment/11781.pdf';const note='安中市一般廃棄物処理基本計画（令和6年3月）PDF43ページ（本文23ページ）表3-8に当初設計・施工 株式会社タクマ、平成7年6月着工・平成10年3月竣工、135t/日・2炉を明記。平成28～31年の基幹改良（株式会社スガテック）は別工事として区別。';if(!f.builder){f.builder='株式会社タクマ';f.builder_source=source;f.builder_scope=note;f.builder_research_status='一次資料確認済み・当初設計施工';}else{f.builder_additional_research_note=[f.builder_additional_research_note,note].filter(Boolean).join(' ／ ');f.builder_additional_research_urls=[f.builder_additional_research_urls,source].filter(Boolean).join(' | ');}})();